import re


def rule_ffo4_total_receipts_table(doc: dict) -> list[dict]:
    try:
        lines = doc.get("lines") or []
        if not lines:
            return []

        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "").strip()).lower()

        def join_window(start: int, end: int) -> str:
            parts = []
            for i in range(max(0, start), min(len(lines), end)):
                text = (lines[i].get("text") or "").strip()
                if text:
                    parts.append(text)
            return "\n".join(parts).strip()

        def extract_numbers(text: str) -> list[str]:
            return re.findall(r"\d[\d,]*", text or "")

        def has_fytd_narrative() -> bool:
            for item in lines:
                low = norm(item.get("text") or "")
                if "federal receipts" not in low and "total federal receipts" not in low:
                    continue
                if "fytd" not in low and "fiscal year to date" not in low and "fiscal year-to-date" not in low:
                    continue
                if any(key in low for key in ("were $", "totaled $", "jumped by $", "were up by $", "up by $")):
                    return True
            return False

        if has_fytd_narrative():
            return []

        heading_idx = None
        for idx, line in enumerate(lines):
            low = norm(line.get("text") or "")
            if "table ffo-4" in low and "summary of u.s. government receipts by source and outlays by agency" in low:
                heading_idx = idx
                break
        if heading_idx is None:
            for idx, line in enumerate(lines):
                low = norm(line.get("text") or "")
                if "table ffo-4" in low and "summary of u.s. government receipts by source and outlays by" in low:
                    heading_idx = idx
                    break
        if heading_idx is None:
            return []

        results = []
        search_limit = min(len(lines), heading_idx + 800)
        for idx in range(heading_idx, search_limit):
            low = norm(lines[idx].get("text") or "")
            if "total receipts" not in low:
                continue
            nums = []
            for j in range(idx, min(len(lines), idx + 8)):
                nums.extend(extract_numbers(lines[j].get("text") or ""))
                if len(nums) >= 4:
                    break
            if len(nums) < 4:
                continue
            answer = nums[3]
            span = {"text": answer}
            if lines[idx].get("page_no") is not None:
                span["page_no"] = lines[idx].get("page_no")
            if lines[idx].get("line_no") is not None:
                span["line_no"] = lines[idx].get("line_no")
            results.append(span)
            break

        return results
    except Exception:
        return []

    return coerced


def _span_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no"),
        span.get("paragraph_no"),
        span.get("line_no"),
        span.get("text"),
    )


def _sort_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no", 10**9),
        span.get("paragraph_no", 10**9),
        span.get("line_no", 10**9),
        span.get("text", ""),
    )


def _list_rule_files(rules_dir: Path, rule_names: list[str] | None = None) -> list[Path]:
    if rule_names:
        files = [rules_dir / f"{name}.py" for name in rule_names]
        return [path for path in files if path.exists()]
    return sorted(path for path in rules_dir.glob("rule_*.py") if path.is_file())


def _apply_rule_files(document: dict[str, Any], rule_files: list[Path]) -> dict[str, Any]:
    spans: list[dict[str, Any]] = []
    rules_applied: list[str] = []
    rules_no_hits: list[str] = []
    rule_errors: list[str] = []

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
            raw_result = rule_fn(document)
        except Exception as exc:
            rule_errors.append(f"{rule_name}: {exc}")
            rules_no_hits.append(rule_name)
            continue

        if not isinstance(raw_result, list):
            rules_no_hits.append(rule_name)
            continue

        coerced = [_coerce_span(item) for item in raw_result]
        cleaned = [item for item in coerced if item]
        if cleaned:
            spans.extend(cleaned)
            rules_applied.append(rule_name)
        else:
            rules_no_hits.append(rule_name)

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for span in spans:
        key = _span_key(span)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(span)

    deduped.sort(key=_sort_key)
    retrieved_text = "\n\n".join(span["text"] for span in deduped) if deduped else ""

    return {
        "retrieved_spans": deduped,
        "retrieved_text": retrieved_text,
        "retrieved_token_count": _count_tokens(retrieved_text),
        "rules_applied": rules_applied,
        "rules_no_hits": rules_no_hits,
        "rule_errors": rule_errors,
    }


def _qa_call(question: str, retrieved_text: str, *, model_name: str = "gpt54") -> tuple[str | None, int, int, float]:
    model_mod = importlib.import_module(f"models.{model_name}")
    t0 = time.time()
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {"role": "system", "content": _QA_SYSTEM},
            {"role": "user", "content": f"Passage:\n{retrieved_text}\n\nQuestion: {question}"},
        ],
        max_completion_tokens=500,
        temperature=0.0,
    )
    latency = round(time.time() - t0, 3)
    answer = (response.choices[0].message.content or "").strip() or None
    usage = response.usage
    return (
        answer,
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
        latency,
    )

